#include <iostream>
#include <numeric>
using namespace std;

using u64 = unsigned long long;
const u64 mod = 998244353;
const int dmax = 19;
u64 p10[dmax + 1];
int main() {
  p10[0] = 1;
  for (int i = 1; i <= dmax; i++) p10[i] = p10[i - 1] * 10;

  int T;
  cin >> T;
  while (T--) {
    u64 N, M;
    cin >> N >> M;
    u64 ans = 0;
    for (int d = 1; d <= dmax; d++) {
      u64 L = p10[d - 1];
      u64 R = min(p10[d], N + 1);
      if (L >= R) break;
      u64 g = gcd(p10[d] - 1, M);
      ans += ((R - L) % mod) * ((N / (M / g)) % mod);
      ans %= mod;
    }
    cout << ans << "\n";
  }
}
